subagents.output_schema_json:
{
  "additionalProperties": false,
  "properties": {
    "client": {
      "maxLength": 64,
      "pattern": "^[A-Za-z0-9 ._-]+$",
      "type": "string"
    },
    "drift_indicators": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "action": {
            "enum": [
              "buy",
              "sell",
              "hold"
            ]
          },
          "asset_class": {
            "maxLength": 64,
            "type": "string"
          },
          "current_weight": {
            "maxLength": 16,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "drift_pct": {
            "maxLength": 16,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          },
          "target_weight": {
            "maxLength": 16,
            "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
            "type": "string"
          }
        },
        "type": "object"
      },
      "maxItems": 50,
      "type": "array"
    },
    "harvest_candidates": {
      "items": {
        "description": "Tax-loss harvest candidates with unrealized loss amounts",
        "type": "object"
      },
      "maxItems": 50,
      "type": "array"
    },
    "performance_metrics": {
      "additionalProperties": false,
      "properties": {
        "beta": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "portfolio_var": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "sharpe_ratio": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "total_return_1y": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        },
        "total_return_ytd": {
          "maxLength": 16,
          "pattern": "^-?[0-9]+(\\.[0-9]+)?$",
          "type": "string"
        }
      },
      "type": "object"
    },
    "retirement_projection": {
      "description": "Retirement readiness summary and projected income",
      "type": "object"
    }
  },
  "required": [
    "client",
    "performance_metrics"
  ],
  "type": "object"
}

{
  "additionalProperties": false,
  "properties": {
    "client": {
      "maxLength": 64,
      "pattern": "^[A-Za-z0-9._-]+$",
      "type": "string"
    },
    "portfolio": {
      "description": "Holdings and computed portfolio statistics keyed by asset class",
      "type": "object"
    }
  },
  "required": [
    "client",
    "portfolio"
  ],
  "type": "object"
}
